    ('S17', 11018, 'negocio', 'Negócio', 'sao_rafael', 'Parte I · Agente · Hospital São Rafael (jun/2025)', 'cobertura', 'Cobertura de preço pactuado', 'M07', 'MEDIA', false, 'especialista_contas_medicas', 'RB-COBERTURA', 'Códigos fora do Anexo I crescendo (Cl. 2.3): pedir aditivo ou tabela de referência', 'banda histórica ±3σ', true),
    ('S18', 11019, 'negocio', 'Negócio', 'sao_rafael', 'Parte I · Agente · Hospital São Rafael (jun/2025)', 'invariantes', 'Apontamentos que violam invariantes', 'M26', 'CRITICA', true, 'juridico', 'RB-INVARIANTE', 'Envio bloqueado. Corrigir o motor ou a regra; reprocessar o run', 'invariante jurídico', true),
    ('S19', 11020, 'negocio', 'Negócio', 'sao_rafael', 'Parte I · Agente · Hospital São Rafael (jun/2025)', 'invariantes', 'Itens com mais de uma glosa', 'sql', 'CRITICA', true, 'engenheiro_dados', 'RB-INVARIANTE', 'Envio bloqueado. Duplicidade no motor ou no merge do fato', 'invariante: no máximo 1 glosa por item (grão do fato)', true),
    ('S20', 11021, 'negocio', 'Negócio', 'sao_rafael', 'Parte I · Agente · Hospital São Rafael (jun/2025)', 'invariantes', 'Contas com glosa maior que o cobrado', 'sql', 'CRITICA', true, 'juridico', 'RB-INVARIANTE', 'Envio bloqueado. Revisar a regra de pacote/escopo de conta', 'invariante: Σ glosa da conta ≤ total da conta', true),
    ('S21', 11022, 'negocio', 'Negócio', 'sao_rafael', 'Parte I · Agente · Hospital São Rafael (jun/2025)', 'invariantes', 'Apontamentos sem item auditado (órfãos)', 'sql', 'CRITICA', true, 'engenheiro_dados', 'RB-INVARIANTE', 'Envio bloqueado. Lineage quebrada entre motor e fato', 'invariante: integridade referencial', true),
    ('S22', 20023, 'semantica', 'Aderência semântica', 'plataforma', 'Aderência semântica', 'aderencia', 'Aderência semântica (itens com conceito)', 'M08', 'ALTA', false, 'analytics_engineer', 'RB-SEMANTICA', 'Código sem conceito: fila do Especialista (ops.ia_sugestoes_conceito); nunca mapear sem aprovação', 'meta da camada semântica (100%)', true),
    ('S23', 20024, 'semantica', 'Aderência semântica', 'plataforma', 'Aderência semântica', 'aderencia', 'Conflito semântico (ex.: PS × Eletivo)', 'M09', 'MEDIA', false, 'especialista_contas_medicas', 'RB-SEMANTICA', 'Conflitos vão para REVISAO_HUMANA (AMB-01); se crescem, o prestador mudou a codificação', 'premissa AMB-21', true),
    ('S24', 20025, 'semantica', 'Aderência semântica', 'plataforma', 'Aderência semântica', 'versionamento', 'Versões da semântica num mesmo run', 'sql', 'CRITICA', true, 'analytics_engineer', 'RB-SEMANTICA', 'Envio bloqueado. Run misturou versões do glossário: reprocessar', 'invariante: um run, uma versão', true),
    ('S25', 20026, 'semantica', 'Aderência semântica', 'plataforma', 'Aderência semântica', 'versionamento', 'Versões do contrato num mesmo run', 'sql', 'CRITICA', true, 'engenheiro_dados', 'RB-SEMANTICA', 'Envio bloqueado. Conferir dim_contrato (SCD2) e vigência', 'invariante: um run, um contrato vigente', true),
    ('S26', 30027, 'dados', 'Engenharia de dados', 'plataforma', 'Engenharia de dados', 'qualidade', 'Expectations de falha reprovadas (último run)', 'sql', 'CRITICA', true, 'engenheiro_dados', 'RB-DADOS', 'Envio bloqueado. Abrir ops.dq_resultados do run e a expectation reprovada', 'expectations E* com ação fail (src/arvo/medallion/expectations.yaml)', true),
    ('S27', 30028, 'dados', 'Engenharia de dados', 'plataforma', 'Engenharia de dados', 'qualidade', 'Taxa de quarentena (último run)', 'sql', 'ALTA', false, 'engenheiro_dados', 'RB-DADOS', 'Ler os motivos da quarentena; código novo vai para a fila semântica (S22)', 'premissa AMB-21', true),
    ('S28', 30029, 'dados', 'Engenharia de dados', 'plataforma', 'Engenharia de dados', 'qualidade', 'Pass rate por dimensão de qualidade (último run)', 'sql', 'MEDIA', false, 'engenheiro_dados', 'RB-DADOS', 'Dimensão degradada: abrir as expectations dela e comparar com o run anterior', 'premissa AMB-21', true),
    ('S30', 40030, 'ia', 'IA', 'plataforma', 'IA', 'qualidade_saida', 'Schema válido', 'taxa_schema_valido', 'ALTA', false, 'cientista_dados', 'RB-IA', 'revisar prompt/schema; rodar golden set do provedor', 'src/arvo/ai/config/alertas_ia.yaml', true),
    ('S31', 40031, 'ia', 'IA', 'plataforma', 'IA', 'qualidade_saida', 'Recusa', 'taxa_recusa', 'MEDIA', false, 'cientista_dados', 'RB-IA', 'ver stop_detalhe; avaliar fallback de provedor', 'src/arvo/ai/config/alertas_ia.yaml', true),
    ('S32', 40032, 'ia', 'IA', 'plataforma', 'IA', 'qualidade_saida', 'Truncamento', 'taxa_truncamento', 'MEDIA', false, 'cientista_dados', 'RB-IA', 'aumentar max_output_tokens ou dividir a tarefa', 'src/arvo/ai/config/alertas_ia.yaml', true),
    ('S33', 40033, 'ia', 'IA', 'plataforma', 'IA', 'resiliencia', 'Erro', 'taxa_erro', 'ALTA', false, 'engenheiro_dados', 'RB-IA', 'provedor degradado: checar circuito e fallback', 'src/arvo/ai/config/alertas_ia.yaml', true),
    ('S34', 40034, 'ia', 'IA', 'plataforma', 'IA', 'resiliencia', 'Fallback de provedor', 'taxa_fallback', 'MEDIA', false, 'engenheiro_dados', 'RB-IA', 'primário instável: abrir incidente com o provedor', 'src/arvo/ai/config/alertas_ia.yaml', true),
    ('S35', 40035, 'ia', 'IA', 'plataforma', 'IA', 'governanca', 'Bloqueio por política de dados', 'taxa_bloqueio_politica', 'CRITICA', true, 'engenheiro_dados', 'RB-IA', 'BUG de configuração: tarefa tentou enviar classe de dado proibida', 'src/arvo/ai/config/alertas_ia.yaml', true),
    ('S36', 40036, 'ia', 'IA', 'plataforma', 'IA', 'resiliencia', 'Bloqueio por circuito', 'taxa_bloqueio_circuito', 'ALTA', false, 'engenheiro_dados', 'RB-IA', 'adapter com falhas consecutivas: investigar antes de reabrir', 'src/arvo/ai/config/alertas_ia.yaml', true),
    ('S37', 40037, 'ia', 'IA', 'plataforma', 'IA', 'custo_latencia', 'Latência p95 (ms)', 'latencia_p95_ms', 'MEDIA', false, 'engenheiro_dados', 'RB-IA', 'considerar tier menor ou batch', 'src/arvo/ai/config/alertas_ia.yaml', true),
    ('S38', 40038, 'ia', 'IA', 'plataforma', 'IA', 'governanca', 'Parâmetro pedido e não aplicado', 'pct_param_ignorado', 'INFO', false, 'cientista_dados', 'RB-IA', 'informativo: parâmetro pedido e não aceito pelo modelo', 'src/arvo/ai/config/alertas_ia.yaml', true),
    ('S39', 40039, 'ia', 'IA', 'plataforma', 'IA', 'governanca', 'Drift de modelo', 'drift_modelo', 'ALTA', false, 'cientista_dados', 'RB-IA', 'modelo servido diferente do pedido ou mais de um modelo servido → rodar golden set antes de aceitar', 'src/arvo/ai/config/alertas_ia.yaml (drift_modelo)', true)
  AS t(id_indicador, ordem, camada, camada_titulo, escopo, secao, familia, nome, definicao, severidade, bloqueia_envio, dono,
       runbook, acao, origem_banda, fonte_disponivel)
),
medicoes AS (
  SELECT 'S01' AS id_indicador, recorte, valor, CAST(0.02 AS DOUBLE) AS banda_min, CAST(NULL AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT 'total' AS recorte, CAST(valor AS DOUBLE) AS valor, row_number() OVER (PARTITION BY 'total' ORDER BY competencia DESC) AS rn FROM (SELECT competencia, MEASURE(indice_norte) AS valor FROM semantic.mv_funil_economia GROUP BY competencia) q) s WHERE rn = 1
  UNION ALL
  SELECT 'S02' AS id_indicador, recorte, valor, CAST(0.8 AS DOUBLE) AS banda_min, CAST(NULL AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT 'total' AS recorte, CAST(valor AS DOUBLE) AS valor, row_number() OVER (PARTITION BY 'total' ORDER BY competencia DESC) AS rn FROM (SELECT competencia, MEASURE(atingimento_meta) AS valor FROM semantic.mv_funil_economia GROUP BY competencia) q) s WHERE rn = 1
  UNION ALL
  SELECT 'S03' AS id_indicador, recorte, valor, mu - 3 * sd AS banda_min, mu + 3 * sd AS banda_max, n_historico, CAST(6 AS INT) AS historico_min FROM (SELECT concat('regra_principal=', CAST(regra_principal AS STRING)) AS recorte, CAST(valor AS DOUBLE) AS valor, avg(valor) OVER (PARTITION BY concat('regra_principal=', CAST(regra_principal AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS mu, stddev_samp(valor) OVER (PARTITION BY concat('regra_principal=', CAST(regra_principal AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS sd, CAST(count(valor) OVER (PARTITION BY concat('regra_principal=', CAST(regra_principal AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS INT) AS n_historico, row_number() OVER (PARTITION BY concat('regra_principal=', CAST(regra_principal AS STRING)) ORDER BY competencia DESC) AS rn FROM (SELECT competencia, regra_principal, MEASURE(taxa_glosa) AS valor FROM semantic.mv_auditoria_glosa WHERE regra_principal IS NOT NULL GROUP BY competencia, regra_principal) q) s WHERE rn = 1
  UNION ALL
  SELECT 'S04' AS id_indicador, recorte, valor, mu - 3 * sd AS banda_min, mu + 3 * sd AS banda_max, n_historico, CAST(6 AS INT) AS historico_min FROM (SELECT 'total' AS recorte, CAST(valor AS DOUBLE) AS valor, avg(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS mu, stddev_samp(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS sd, CAST(count(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS INT) AS n_historico, row_number() OVER (PARTITION BY 'total' ORDER BY competencia DESC) AS rn FROM (SELECT competencia, MEASURE(gap_cobrado_vs_pactuado) AS valor FROM semantic.mv_auditoria_glosa GROUP BY competencia) q) s WHERE rn = 1
  UNION ALL
  SELECT 'S40' AS id_indicador, recorte, valor, mu - 3 * sd AS banda_min, mu + 3 * sd AS banda_max, n_historico, CAST(6 AS INT) AS historico_min FROM (SELECT 'total' AS recorte, CAST(valor AS DOUBLE) AS valor, avg(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS mu, stddev_samp(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS sd, CAST(count(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS INT) AS n_historico, row_number() OVER (PARTITION BY 'total' ORDER BY competencia DESC) AS rn FROM (SELECT competencia, MEASURE(taxa_glosa) AS valor FROM semantic.mv_auditoria_glosa GROUP BY competencia) q) s WHERE rn = 1
  UNION ALL
  SELECT 'S05' AS id_indicador, concat('regra_principal=', CAST(regra_principal AS STRING)) AS recorte, CAST(valor AS DOUBLE) AS valor, CAST(0.98 AS DOUBLE) AS banda_min, CAST(NULL AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT regra_principal, MEASURE(precisao_auditada) AS valor FROM semantic.mv_qualidade_auditoria WHERE regra_principal IS NOT NULL GROUP BY regra_principal) q
  UNION ALL
  SELECT 'S06' AS id_indicador, recorte, CAST(valor AS DOUBLE) AS valor, CAST(0.95 AS DOUBLE) AS banda_min, CAST(NULL AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT concat('regra_principal=', regra_principal) AS recorte, (p + z*z/(2*n) - z*sqrt(p*(1-p)/n + z*z/(4*n*n))) / (1 + z*z/n) AS valor FROM (SELECT regra_principal, count(*) AS n, avg(CAST(auditor_indevido AS INT)) AS p, 1.959964 AS z FROM gold.fato_auditoria_amostral WHERE estrato = 'GLOSADO' AND regra_principal IS NOT NULL GROUP BY regra_principal) t) q
  UNION ALL
  SELECT 'S07' AS id_indicador, 'total' AS recorte, CAST(valor AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0.05 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT MEASURE(taxa_indevido_nao_detectado) AS valor FROM semantic.mv_qualidade_auditoria) q
  UNION ALL
  SELECT 'S10' AS id_indicador, recorte, valor, mu - 3 * sd AS banda_min, mu + 3 * sd AS banda_max, n_historico, CAST(3 AS INT) AS historico_min FROM (SELECT 'total' AS recorte, CAST(valor AS DOUBLE) AS valor, avg(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS mu, stddev_samp(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS sd, CAST(count(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS INT) AS n_historico, row_number() OVER (PARTITION BY 'total' ORDER BY competencia DESC) AS rn FROM (SELECT competencia, MEASURE(taxa_ativacao) AS valor FROM semantic.mv_funil_economia GROUP BY competencia) q) s WHERE rn = 1
  UNION ALL
  SELECT 'S11' AS id_indicador, recorte, valor, mu - 3 * sd AS banda_min, mu + 3 * sd AS banda_max, n_historico, CAST(3 AS INT) AS historico_min FROM (SELECT concat('inteligencia=', CAST(inteligencia AS STRING)) AS recorte, CAST(valor AS DOUBLE) AS valor, avg(valor) OVER (PARTITION BY concat('inteligencia=', CAST(inteligencia AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS mu, stddev_samp(valor) OVER (PARTITION BY concat('inteligencia=', CAST(inteligencia AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS sd, CAST(count(valor) OVER (PARTITION BY concat('inteligencia=', CAST(inteligencia AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS INT) AS n_historico, row_number() OVER (PARTITION BY concat('inteligencia=', CAST(inteligencia AS STRING)) ORDER BY competencia DESC) AS rn FROM (SELECT competencia, inteligencia, MEASURE(taxa_envio) AS valor FROM semantic.mv_funil_economia WHERE inteligencia IS NOT NULL GROUP BY competencia, inteligencia) q) s WHERE rn = 1
  UNION ALL
  SELECT 'S12' AS id_indicador, recorte, valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0.05 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT 'total' AS recorte, CAST(valor AS DOUBLE) AS valor, row_number() OVER (PARTITION BY 'total' ORDER BY competencia DESC) AS rn FROM (SELECT competencia, MEASURE(taxa_perda_registro) AS valor FROM semantic.mv_funil_economia GROUP BY competencia) q) s WHERE rn = 1
  UNION ALL
  SELECT 'S13' AS id_indicador, recorte, CAST(valor AS DOUBLE) AS valor, CAST(0.8 AS DOUBLE) AS banda_min, CAST(NULL AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT concat('inteligencia=', inteligencia) AS recorte, (SUM(vl_efetivado) / NULLIF(SUM(vl_enviado_prestador), 0)) / NULLIF(MAX(taxa_efetivacao_benchmark), 0) AS valor FROM gold.fato_funil_economia WHERE competencia = (SELECT max(competencia) FROM gold.fato_funil_economia) AND status_inteligencia = 'Ligada' GROUP BY inteligencia) q
  UNION ALL
  SELECT 'S14' AS id_indicador, recorte, valor, mu - 3 * sd AS banda_min, mu + 3 * sd AS banda_max, n_historico, CAST(6 AS INT) AS historico_min FROM (SELECT concat('id_prestador=', CAST(id_prestador AS STRING)) AS recorte, CAST(valor AS DOUBLE) AS valor, avg(valor) OVER (PARTITION BY concat('id_prestador=', CAST(id_prestador AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS mu, stddev_samp(valor) OVER (PARTITION BY concat('id_prestador=', CAST(id_prestador AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS sd, CAST(count(valor) OVER (PARTITION BY concat('id_prestador=', CAST(id_prestador AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS INT) AS n_historico, row_number() OVER (PARTITION BY concat('id_prestador=', CAST(id_prestador AS STRING)) ORDER BY competencia DESC) AS rn FROM (SELECT competencia, id_prestador, MEASURE(pct_contas_com_glosa) AS valor FROM semantic.mv_auditoria_glosa WHERE id_prestador IS NOT NULL GROUP BY competencia, id_prestador) q) s WHERE rn = 1
  UNION ALL
  SELECT 'S15' AS id_indicador, recorte, CAST(valor AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0.5 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT 'total' AS recorte, SUM(CASE WHEN rk <= 10 THEN g END) / NULLIF(SUM(g), 0) AS valor FROM (SELECT id_conta, SUM(vl_glosado) AS g, row_number() OVER (ORDER BY SUM(vl_glosado) DESC) AS rk FROM gold.fato_item_auditado WHERE glosado GROUP BY id_conta) t) q
  UNION ALL
  SELECT 'S16' AS id_indicador, recorte, valor, mu - 3 * sd AS banda_min, mu + 3 * sd AS banda_max, n_historico, CAST(6 AS INT) AS historico_min FROM (SELECT concat('regra_principal=', CAST(regra_principal AS STRING)) AS recorte, CAST(valor AS DOUBLE) AS valor, avg(valor) OVER (PARTITION BY concat('regra_principal=', CAST(regra_principal AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS mu, stddev_samp(valor) OVER (PARTITION BY concat('regra_principal=', CAST(regra_principal AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS sd, CAST(count(valor) OVER (PARTITION BY concat('regra_principal=', CAST(regra_principal AS STRING)) ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS INT) AS n_historico, row_number() OVER (PARTITION BY concat('regra_principal=', CAST(regra_principal AS STRING)) ORDER BY competencia DESC) AS rn FROM (SELECT competencia, regra_principal, MEASURE(itens_glosados) AS valor FROM semantic.mv_auditoria_glosa WHERE regra_principal IS NOT NULL GROUP BY competencia, regra_principal) q) s WHERE rn = 1
  UNION ALL
  SELECT 'S17' AS id_indicador, recorte, valor, mu - 3 * sd AS banda_min, mu + 3 * sd AS banda_max, n_historico, CAST(6 AS INT) AS historico_min FROM (SELECT 'total' AS recorte, CAST(valor AS DOUBLE) AS valor, avg(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS mu, stddev_samp(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS sd, CAST(count(valor) OVER (PARTITION BY 'total' ORDER BY competencia ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS INT) AS n_historico, row_number() OVER (PARTITION BY 'total' ORDER BY competencia DESC) AS rn FROM (SELECT competencia, MEASURE(cobertura_preco_pactuado) AS valor FROM semantic.mv_auditoria_glosa GROUP BY competencia) q) s WHERE rn = 1
  UNION ALL
  SELECT 'S18' AS id_indicador, 'total' AS recorte, CAST(valor AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT MEASURE(violacoes_invariantes) AS valor FROM semantic.mv_apontamento) q
  UNION ALL
  SELECT 'S19' AS id_indicador, recorte, CAST(valor AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT 'total' AS recorte, CAST(count(*) AS DOUBLE) AS valor FROM (SELECT id_item FROM gold.fato_apontamento GROUP BY id_item HAVING count(*) > 1) t) q
  UNION ALL
  SELECT 'S20' AS id_indicador, recorte, CAST(valor AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT 'total' AS recorte, CAST(count(*) AS DOUBLE) AS valor FROM (SELECT id_conta FROM gold.fato_item_auditado GROUP BY id_conta HAVING SUM(coalesce(vl_glosado, 0)) > SUM(vl_cobrado)) t) q
  UNION ALL
  SELECT 'S21' AS id_indicador, recorte, CAST(valor AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT 'total' AS recorte, CAST(count(*) AS DOUBLE) AS valor FROM gold.fato_apontamento a LEFT ANTI JOIN gold.fato_item_auditado i ON a.id_item = i.id_item) q
  UNION ALL
  SELECT 'S22' AS id_indicador, 'total' AS recorte, CAST(valor AS DOUBLE) AS valor, CAST(1.0 AS DOUBLE) AS banda_min, CAST(NULL AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT MEASURE(aderencia_semantica) AS valor FROM semantic.mv_auditoria_glosa) q
  UNION ALL
  SELECT 'S23' AS id_indicador, 'total' AS recorte, CAST(valor AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0.01 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT MEASURE(taxa_conflito_semantico) AS valor FROM semantic.mv_auditoria_glosa) q
  UNION ALL
  SELECT 'S24' AS id_indicador, recorte, CAST(valor AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(1 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT concat('run_id=', run_id) AS recorte, CAST(count(DISTINCT versao_semantica) AS DOUBLE) AS valor FROM gold.fato_item_auditado GROUP BY run_id) q
  UNION ALL
  SELECT 'S25' AS id_indicador, recorte, CAST(valor AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(1 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT concat('run_id=', run_id) AS recorte, CAST(count(DISTINCT versao_contrato) AS DOUBLE) AS valor FROM gold.fato_item_auditado GROUP BY run_id) q
  UNION ALL
  SELECT 'S26' AS id_indicador, recorte, CAST(valor AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT 'total' AS recorte, CAST(coalesce(SUM(reprovados), 0) AS DOUBLE) AS valor FROM ops.dq_resultados WHERE acao = 'fail' AND run_id = (SELECT max_by(run_id, executado_em) FROM ops.dq_resultados)) q
  UNION ALL
  SELECT 'S27' AS id_indicador, recorte, CAST(valor AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0.02 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT 'total' AS recorte, (SELECT count(*) FROM quarantine.item_conta_rejeitado) / NULLIF((SELECT count(*) FROM bronze.sinistro_raw), 0) AS valor) q
  UNION ALL
  SELECT 'S28' AS id_indicador, recorte, CAST(valor AS DOUBLE) AS valor, CAST(0.99 AS DOUBLE) AS banda_min, CAST(NULL AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM (SELECT concat('dimensao=', dimensao) AS recorte, 1 - SUM(reprovados) / NULLIF(SUM(avaliados), 0) AS valor FROM ops.dq_resultados WHERE run_id = (SELECT max_by(run_id, executado_em) FROM ops.dq_resultados) GROUP BY dimensao) q
  UNION ALL
  SELECT 'S30' AS id_indicador, concat('tarefa=', task_id, ' · adapter=', adapter) AS recorte, CAST(taxa_schema_valido AS DOUBLE) AS valor, CAST(0.98 AS DOUBLE) AS banda_min, CAST(NULL AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM ops.v_ia_sanidade WHERE dia = (SELECT max(dia) FROM ops.v_ia_sanidade)
  UNION ALL
  SELECT 'S31' AS id_indicador, concat('tarefa=', task_id, ' · adapter=', adapter) AS recorte, CAST(taxa_recusa AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0.01 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM ops.v_ia_sanidade WHERE dia = (SELECT max(dia) FROM ops.v_ia_sanidade)
  UNION ALL
  SELECT 'S32' AS id_indicador, concat('tarefa=', task_id, ' · adapter=', adapter) AS recorte, CAST(taxa_truncamento AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0.01 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM ops.v_ia_sanidade WHERE dia = (SELECT max(dia) FROM ops.v_ia_sanidade)
  UNION ALL
  SELECT 'S33' AS id_indicador, concat('tarefa=', task_id, ' · adapter=', adapter) AS recorte, CAST(taxa_erro AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0.05 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM ops.v_ia_sanidade WHERE dia = (SELECT max(dia) FROM ops.v_ia_sanidade)
  UNION ALL
  SELECT 'S34' AS id_indicador, concat('tarefa=', task_id, ' · adapter=', adapter) AS recorte, CAST(taxa_fallback AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0.1 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM ops.v_ia_sanidade WHERE dia = (SELECT max(dia) FROM ops.v_ia_sanidade)
  UNION ALL
  SELECT 'S35' AS id_indicador, concat('tarefa=', task_id, ' · adapter=', adapter) AS recorte, CAST(taxa_bloqueio_politica AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0.0 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM ops.v_ia_sanidade WHERE dia = (SELECT max(dia) FROM ops.v_ia_sanidade)
  UNION ALL
  SELECT 'S36' AS id_indicador, concat('tarefa=', task_id, ' · adapter=', adapter) AS recorte, CAST(taxa_bloqueio_circuito AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0.0 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM ops.v_ia_sanidade WHERE dia = (SELECT max(dia) FROM ops.v_ia_sanidade)
  UNION ALL
  SELECT 'S37' AS id_indicador, concat('tarefa=', task_id, ' · adapter=', adapter) AS recorte, CAST(latencia_p95_ms AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(120000 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM ops.v_ia_sanidade WHERE dia = (SELECT max(dia) FROM ops.v_ia_sanidade)
  UNION ALL
  SELECT 'S38' AS id_indicador, concat('tarefa=', task_id, ' · adapter=', adapter) AS recorte, CAST(pct_param_ignorado AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(1.0 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM ops.v_ia_sanidade WHERE dia = (SELECT max(dia) FROM ops.v_ia_sanidade)
  UNION ALL
  SELECT 'S39' AS id_indicador, concat('tarefa=', task_id, ' · adapter=', adapter) AS recorte, CAST(CAST(drift_modelo AS INT) AS DOUBLE) AS valor, CAST(NULL AS DOUBLE) AS banda_min, CAST(0 AS DOUBLE) AS banda_max, CAST(NULL AS INT) AS n_historico, CAST(NULL AS INT) AS historico_min FROM ops.v_ia_sanidade WHERE dia = (SELECT max(dia) FROM ops.v_ia_sanidade)
)
SELECT m.ordem, m.id_indicador, m.camada, m.camada_titulo, m.escopo, m.secao, m.familia, m.nome, m.definicao, m.severidade,
       m.bloqueia_envio, m.dono, m.runbook, m.acao, m.origem_banda,
       coalesce(d.recorte, 'total') AS recorte, d.valor, d.banda_min, d.banda_max, d.n_historico, d.historico_min,
       CASE WHEN NOT m.fonte_disponivel THEN 'SEM_FONTE'
            WHEN d.historico_min IS NOT NULL AND coalesce(d.n_historico, 0) < d.historico_min THEN 'CALIBRANDO'
            WHEN d.valor IS NULL THEN 'SEM_DADO'
            WHEN d.valor < d.banda_min OR d.valor > d.banda_max THEN 'ALERTA'
            ELSE 'OK' END AS status,
       current_timestamp() AS avaliado_em
FROM meta m LEFT JOIN medicoes d ON m.id_indicador = d.id_indicador;
